class Solution {
public:
    int countStaircase(vector<int>& nums) {
        int n = nums.size();
        const int MAXV = 100000;

        vector<int> global(MAXV + 1, 0);
        vector<int> counts;

        for (int x : nums)
            ++global[x];

        for (int f : global) {
            if (f > 0)
                counts.push_back(f);
        }

        sort(counts.rbegin(), counts.rend());

        // Maximum globally feasible staircase size.
        int K = 0;

        for (int k = 1;
             k <= (int)counts.size() &&
             1LL * k * (k + 1) / 2 <= n;
             ++k) {

            bool possible = true;

            for (int j = 0; j < k; ++j) {
                if (counts[j] < k - j) {
                    possible = false;
                    break;
                }
            }

            if (!possible)
                break;

            K = k;
        }

        // Every single-element subarray is valid.
        int answer = n;

        if (K < 2)
            return answer;

        int maxLen = K * (K + 1) / 2;

        vector<int> freq(MAXV + 1, 0);
        vector<int> rank(MAXV + 1, 0);
        vector<int> stamp(MAXV + 1, 0);

        int generation = 0;

        for (int left = 0; left < n; ++left) {
            ++generation;

            int distinct = 0;
            int bad = 0;

            int bound = min(n, left + maxLen);

            for (int right = left; right < bound; ++right) {
                int x = nums[right];

                if (stamp[x] != generation) {
                    stamp[x] = generation;
                    freq[x] = 0;
                    rank[x] = ++distinct;

                    if (distinct > K)
                        break;
                }

                int target = rank[x];
                int oldFreq = freq[x];

                ++freq[x];

                if (oldFreq == 0) {
                    if (target > 1)
                        ++bad;
                } else if (oldFreq == target - 1) {
                    --bad;
                } else if (oldFreq == target) {
                    ++bad;
                }

                // Frequency cannot decrease as we extend
                // the current subarray.
                if (freq[x] > target)
                    break;

                int len = right - left + 1;

                if (distinct >= 2 &&
                    len == distinct * (distinct + 1) / 2 &&
                    bad == 0) {
                    ++answer;
                }
            }
        }

        return answer;
    }
};
